import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _cell_to_dict(cell: Any) -> Dict[str, Any]:
    polygon = None
    if getattr(cell, "polygon", None):
        polygon = [{"x": p.x, "y": p.y} for p in cell.polygon]

    return {
        "row_index": getattr(cell, "row_index", None),
        "column_index": getattr(cell, "column_index", None),
        "row_span": getattr(cell, "row_span", None),
        "column_span": getattr(cell, "column_span", None),
        "kind": getattr(cell, "kind", None),
        "content": getattr(cell, "content", None),
        "bounding_regions": [
            {
                "page_number": getattr(region, "page_number", None),
                "polygon": (
                    [{"x": p.x, "y": p.y} for p in getattr(region, "polygon", [])]
                    if getattr(region, "polygon", None)
                    else None
                ),
            }
            for region in (getattr(cell, "bounding_regions", None) or [])
        ],
        "polygon": polygon,
    }


def _table_to_dict(table: Any) -> Dict[str, Any]:
    cells = getattr(table, "cells", None) or []
    row_count = getattr(table, "row_count", None)
    column_count = getattr(table, "column_count", None)

    rows: List[List[Optional[Dict[str, Any]]]] = []
    if row_count is not None and column_count is not None:
        rows = [[None for _ in range(column_count)] for _ in range(row_count)]
        for cell in cells:
            r = getattr(cell, "row_index", None)
            c = getattr(cell, "column_index", None)
            if r is not None and c is not None and 0 <= r < row_count and 0 <= c < column_count:
                rows[r][c] = _cell_to_dict(cell)
    else:
        for cell in cells:
            r = getattr(cell, "row_index", None)
            c = getattr(cell, "column_index", None)
            while len(rows) <= (r or 0):
                rows.append([])
            while len(rows[r]) <= (c or 0):
                rows[r].append(None)
            rows[r][c] = _cell_to_dict(cell)

    return {
        "row_count": row_count,
        "column_count": column_count,
        "cells": [_cell_to_dict(cell) for cell in cells],
        "rows": rows,
        "bounding_regions": [
            {
                "page_number": getattr(region, "page_number", None),
                "polygon": (
                    [{"x": p.x, "y": p.y} for p in getattr(region, "polygon", [])]
                    if getattr(region, "polygon", None)
                    else None
                ),
            }
            for region in (getattr(table, "bounding_regions", None) or [])
        ],
    }


def extract_tables_and_rows(
    document_path: str,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValueError("Missing Azure Document Intelligence endpoint. Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT.")
    if not key:
        raise ValueError("Missing Azure Document Intelligence key. Set AZURE_DOCUMENT_INTELLIGENCE_KEY.")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)

    result = poller.result()

    tables = []
    for table in getattr(result, "tables", None) or []:
        tables.append(_table_to_dict(table))

    pages = []
    for page in getattr(result, "pages", None) or []:
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
            }
        )

    return {
        "tables": tables,
        "pages": pages,
        "content": getattr(result, "content", None),
    }
